def rgb_to_hex(red, green, blue):
    """Converts an RGB color value to a hexadecimal string."""
    return "#{:02x}{:02x}{:02x}".format(red, green, blue)

def hex_to_rgb(hex_code):
    """Converts a hexadecimal color string to an RGB tuple."""
    return tuple(int(hex_code[i:i+2], 16) for i in (0, 2, 4))

def convert_color():
    """Gets user input for a color to convert and converts it to HEX."""
    user_input = input("Enter an RGB color value (e.g. 255 0 0) or a HEX color code: ")

    if user_input.startswith("#"):
        # Assume user input is a HEX color code
        return hex_to_rgb(user_input)
    else:
        # Assume user input is an RGB color value
        red, green, blue = map(int, user_input.split())
        return rgb_to_hex(red, green, blue)

# Run the program
color = convert_color()
print(f"The converted color is: {color}")
```
